import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { PenTool, Trash2, Plus, Bookmark, Hash } from 'lucide-react';
import GoldButton from '../../components/ui/GoldButton';

const TacticalJournal = () => {
  const [notes, setNotes] = useState(() => {
    const saved = localStorage.getItem('pc_tactical_notes');
    return saved ? JSON.parse(saved) : [
      { id: 1, category: 'STRATEGY', text: 'Never reveal the full extent of your design until completion.', date: '2023.10.24' },
      { id: 2, category: 'BIO-POWER', text: 'Cognitive peak is at 10:00 AM. Schedule all deep work then.', date: '2023.10.25' }
    ];
  });

  const [input, setInput] = useState('');
  const [category, setCategory] = useState('INSIGHT');

  useEffect(() => {
    localStorage.setItem('pc_tactical_notes', JSON.stringify(notes));
  }, [notes]);

  const addNote = () => {
    if (!input.trim()) return;
    const newNote = {
      id: Date.now(),
      category: category.toUpperCase(),
      text: input,
      date: new Date().toLocaleDateString('fa-IR').replace(/\//g, '.')
    };
    setNotes([newNote, ...notes]);
    setInput('');
  };

  const deleteNote = (id) => {
    setNotes(notes.filter(n => n.id !== id));
  };

  return (
    <div className="max-w-4xl mx-auto p-12">
      <header className="mb-16">
        <div className="flex items-center gap-3 mb-4">
          <PenTool className="text-gold w-5 h-5" />
          <h2 className="font-serif text-3xl tracking-[0.4em] uppercase">Tactical Journal</h2>
        </div>
        <p className="text-[10px] text-white/40 tracking-[0.2em] uppercase leading-loose">
          Record the architecture of your thoughts. Every insight is a brick in the sovereign kingdom.
        </p>
      </header>

      {/* Input Section */}
      <section className="mb-20 bg-white/5 border border-white/5 p-8 rounded-2xl backdrop-blur-xl">
        <div className="flex gap-4 mb-6">
          {['Insight', 'Strategy', 'Rule', 'Bio-Power'].map(cat => (
            <button 
              key={cat}
              onClick={() => setCategory(cat)}
              className={`px-4 py-1 text-[8px] tracking-[0.2em] uppercase border transition-all ${category === cat ? 'border-gold text-gold bg-gold/5' : 'border-white/10 text-white/40'}`}
            >
              {cat}
            </button>
          ))}
        </div>
        <div className="relative">
          <textarea 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Document a new strategic protocol..."
            className="w-full bg-transparent border-b border-white/10 py-4 text-white font-serif italic text-lg focus:outline-none focus:border-gold transition-colors resize-none h-24"
          />
          <div className="flex justify-end mt-4">
            <GoldButton onClick={addNote}>
              <Plus className="inline mr-2 w-3 h-3" /> Log Entry
            </GoldButton>
          </div>
        </div>
      </section>

      {/* Notes Grid */}
      <div className="grid grid-cols-1 gap-6">
        <AnimatePresence>
          {notes.map((note, index) => (
            <motion.div
              key={note.id}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 20 }}
              transition={{ delay: index * 0.05 }}
              className="group relative p-8 bg-card border border-white/5 rounded-xl hover:border-gold/20 transition-all"
            >
              <div className="flex justify-between items-start mb-6">
                <div className="flex items-center gap-3">
                  <Hash className="w-3 h-3 text-gold/40" />
                  <span className="text-[9px] font-mono tracking-widest text-gold">{note.category}</span>
                </div>
                <span className="text-[8px] font-mono text-white/20 uppercase tracking-tighter">{note.date}</span>
              </div>
              
              <p className="font-serif text-lg text-white/80 leading-relaxed italic mb-8">
                "{note.text}"
              </p>

              <div className="flex justify-end opacity-0 group-hover:opacity-100 transition-opacity">
                <button 
                  onClick={() => deleteNote(note.id)}
                  className="p-2 text-white/20 hover:text-red-500 transition-colors"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            </motion.div>
          ))}
        </AnimatePresence>
      </div>
    </div>
  );
};

export default TacticalJournal;
